import{_ as o}from"./chunks/cbunmanned-h753-som-pinout.C6FJmq1d.js";import{_ as r,C as d,o as n,c as i,j as e,a as l,E as s,al as p}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"CBUnmanned H753-SOM","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_controller/cbunmanned_h753-som.md","filePath":"en/flight_controller/cbunmanned_h753-som.md"}'),h={name:"en/flight_controller/cbunmanned_h753-som.md"};function u(c,t,m,b,f,P){const a=d("Badge");return n(),i("div",null,[t[0]||(t[0]=e("h1",{id:"cbunmanned-h753-som",tabindex:"-1"},[l("CBUnmanned H753-SOM "),e("a",{class:"header-anchor",href:"#cbunmanned-h753-som","aria-label":'Permalink to "CBUnmanned H753-SOM"'},"​")],-1)),s(a,{type:"tip",text:"PX4 v1.18"}),t[1]||(t[1]=p('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the manufacturer for hardware support or compliance issues.</p></div><p>The <em>CBUnmanned H753-SOM</em> is a System-on-Module (SoM) flight controller built around the STM32H753 microcontroller. It is intended to be mounted on a carrier board that breaks out the I/O and provides power, peripherals, and connectors for a specific vehicle integration.</p><p><img src="'+o+'" alt="CBUnmanned H753-SOM Pinout"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This flight controller is <a href="./../flight_controller/autopilot_manufacturer_supported">manufacturer supported</a>.</p></div><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>MCU:</strong> STM32H753 (32-bit Arm® Cortex®-M7, 480 MHz, 2 MB Flash, 1 MB RAM)</li><li><strong>IMU:</strong> Dual InvenSense ICM-42670-P (on SPI4)</li><li><strong>Barometer:</strong> ST LPS22HB (on I2C1)</li><li><strong>Storage:</strong> microSD card (SDMMC2)</li><li><strong>Interfaces:</strong><ul><li>6x user UARTs (TEL1, TEL2, TEL3, GPS1, GPS2, RC) plus a debug console — flow control on TEL1/TEL2/TEL3</li><li>2x CAN (UAVCAN)</li><li>2x external I2C (one per GPS port for compass) and 1x internal I2C (barometer)</li><li>1x external SPI (the dual IMUs are on a separate internal SPI bus)</li><li>9x PWM outputs (DShot / Bi-Directional DShot supported)</li><li>USB</li><li>Ethernet optional</li></ul></li><li><strong>Power:</strong> Powered from an external regulated 5 V supply (e.g. a BEC on the carrier board). Battery voltage (up to 65 V) and current are monitored via ADC; the voltage sense input is a separate pin behind a voltage divider and does not power the board.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>CAN transceivers require a 5 V supply. USB-only power (≈4.5 V after the input diode) is <strong>not</strong> sufficient to operate the CAN bus.</p></div><h2 id="where-to-buy" tabindex="-1">Where to Buy <a class="header-anchor" href="#where-to-buy" aria-label="Permalink to &quot;Where to Buy&quot;">​</a></h2><p>Check <a href="https://www.cbunmanned.com/" target="_blank" rel="noreferrer">CBUnmanned</a> for availability.</p><h2 id="building-firmware" tabindex="-1">Building Firmware <a class="header-anchor" href="#building-firmware" aria-label="Permalink to &quot;Building Firmware&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users will not need to build this firmware. It is pre-built and automatically installed by <em>QGroundControl</em> when appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target from source:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cbunmanned_h753-som_default</span></span></code></pre></div><h2 id="serial-port-mapping" tabindex="-1">Serial Port Mapping <a class="header-anchor" href="#serial-port-mapping" aria-label="Permalink to &quot;Serial Port Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>Device</th><th>PX4 Default</th><th>Pins (TX / RX)</th><th>Flow Control (CTS / RTS)</th></tr></thead><tbody><tr><td>USART2</td><td>/dev/ttyS0</td><td>TEL1</td><td>PD5 / PA3</td><td>PA0 / PD4</td></tr><tr><td>USART3</td><td>/dev/ttyS1</td><td>GPS1</td><td>PD8 / PD9</td><td>—</td></tr><tr><td>UART4</td><td>/dev/ttyS2</td><td>GPS2</td><td>PC10 / PC11</td><td>—</td></tr><tr><td>UART5</td><td>/dev/ttyS3</td><td>Console</td><td>PC12 / PD2</td><td>—</td></tr><tr><td>USART6</td><td>/dev/ttyS4</td><td>RC</td><td>PC6 / PC7</td><td>—</td></tr><tr><td>UART7</td><td>/dev/ttyS5</td><td>TEL2</td><td>PE8 / PE7</td><td>PE10 / PE9</td></tr><tr><td>UART8</td><td>/dev/ttyS6</td><td>TEL3</td><td>PE1 / PE0</td><td>PD14 / PD15</td></tr></tbody></table><h2 id="pwm-outputs" tabindex="-1">PWM Outputs <a class="header-anchor" href="#pwm-outputs" aria-label="Permalink to &quot;PWM Outputs&quot;">​</a></h2><p>The board provides 9 PWM outputs, all of which support <a href="./../peripherals/dshot">DShot</a> and <a href="./../peripherals/dshot#bidirectional-dshot-telemetry">Bidirectional DShot</a>.</p><p>The outputs are split across 4 timer groups:</p><table tabindex="0"><thead><tr><th>Outputs</th><th>Timer</th></tr></thead><tbody><tr><td>1, 2, 3</td><td>Timer1</td></tr><tr><td>4, 5</td><td>Timer2</td></tr><tr><td>6, 7, 8</td><td>Timer3</td></tr><tr><td>9</td><td>Timer4</td></tr></tbody></table><p>All outputs within the same group must use the same protocol and update rate.</p><h2 id="debug-port" tabindex="-1">Debug Port <a class="header-anchor" href="#debug-port" aria-label="Permalink to &quot;Debug Port&quot;">​</a></h2><p>The system console runs on UART5 (PC12 / PD2). USB CDC ACM is auto-started and provides MAVLink access.</p><p><a id="bootloader"></a></p><h2 id="px4-bootloader-update" tabindex="-1">PX4 Bootloader Update <a class="header-anchor" href="#px4-bootloader-update" aria-label="Permalink to &quot;PX4 Bootloader Update&quot;">​</a></h2><p>Boards that ship without the PX4 bootloader must have it flashed before PX4 firmware can be installed. Download the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/cbunmanned/h753-som/extras/cbunmanned_h753-som_bootloader.bin" target="_blank" rel="noreferrer">cbunmanned_h753-som_bootloader.bin</a> bootloader binary and follow the <a href="./../advanced_config/bootloader_update_from_betaflight#dfu-bootloader-update">DFU Bootloader Update</a> instructions.</p><p>Once the PX4 bootloader is flashed, firmware can be installed normally via <em>QGroundControl</em>.</p>',26))])}const C=r(h,[["render",u]]);export{_ as __pageData,C as default};
